INSERT INTO doctors (id, full_name, slug, bio, active) VALUES ('0f7a70b6-dbc4-36e4-59b4-e1e98ecb36bc', 'BS.CKII Phạm Quốc Yến', 'bs-333', 'BS.CKII Phạm Quốc Yến có hơn 26 năm kinh nghiệm chuyên sâu trong lĩnh vực Cơ xương khớp. Tốt nghiệp Bác sĩ Chuyên khoa tại Đại học Y Dược TP.HCM và tu nghiệp nâng cao tại các bệnh viện tuyến đầu, bác sĩ luôn cẩn trọng, tận tâm và đồng hành sát sao cùng người bệnh trong quá trình thăm khám, chẩn đoán và điều trị.', true) ON CONFLICT (id) DO NOTHING;